    '백 년이었네. 원의 사위 나라로 지낸 세월이. 왕의 이름 앞에는 충(忠) 자가 붙었고, 옷과 머리까지 저들을 따랐지.',
    '나는 변발을 풀고 몽골 옷을 벗었네. 그리고 기철 일당 — 원을 등에 업고 나라를 좀먹던 자들을 베었지.',
