    {'t':'내가 처음부터 이랬던 건 아닐세. 안동 김씨가 왕족을 눈엣가시로 여기던 시절, 나는 일부러 파락호 노릇을 했네.'},
    {'t':'상갓집을 기웃거리며 술을 얻어먹고, 개 취급을 당해도 웃었지. 사람들이 나를 상갓집 개라 불렀네. 그렇게 목숨을 부지하고, 아들을 왕좌에 앉혔지.'},
